// Generated from indicators/*.pine by node scripts/build.mjs. Do not edit.
window.PINE_SOURCES = {
  "high52": "//@version=6\nindicator(title=\"52-Week High\", shorttitle=\"52W High\", overlay=true, max_bars_back=300)\n\n// ─── Inputs ───────────────────────────────────────────────────────────────────\ngrpHigh        = \"52-Week High\"\nlineColorHigh  = input.color(color.new(color.orange, 0), \"Line Color\",         group=grpHigh)\nlineWidth      = input.int(2,      \"Line Width\",    minval=1, maxval=4,         group=grpHigh)\nlineStyle      = input.string(\"Solid\", \"Line Style\", options=[\"Solid\",\"Dashed\",\"Dotted\"], group=grpHigh)\nshowLabel      = input.bool(true,  \"Show Label\",                                group=grpHigh)\nshowDist       = input.bool(true,  \"Show Distance %\",                           group=grpHigh)\nshowPriceLabel = input.bool(true,  \"Show Price on Axis\",                        group=grpHigh)\nalertProxPct   = input.float(2.0,  \"Proximity Alert (%)\", minval=0.0, step=0.1, group=grpHigh)\n\n// ─── Adaptive Lookback ────────────────────────────────────────────────────────\nIDEAL_BARS = 252\nadaptedLen = math.min(bar_index + 1, IDEAL_BARS)\n\n// ─── Logic ────────────────────────────────────────────────────────────────────\nweekHigh52 = ta.highest(high, adaptedLen)\ndistPct    = (close - weekHigh52) / weekHigh52 * 100\nisNearHigh = math.abs(distPct) <= alertProxPct\n\n// ─── Helper ───────────────────────────────────────────────────────────────────\n_lineStyle(s) =>\n    if s == \"Dashed\"\n        line.style_dashed\n    else if s == \"Dotted\"\n        line.style_dotted\n    else\n        line.style_solid\n\n// ─── Price axis label via plot + plotchar trick ───────────────────────────────\n// This is the native way to get a coloured price tag on the right axis\nplot(showPriceLabel ? weekHigh52 : na, \"52W High Level\",\n     color     = lineColorHigh,\n     linewidth = 1,\n     style     = plot.style_linebr,\n     display   = display.price_scale)\n\n// ─── Drawing ──────────────────────────────────────────────────────────────────\nvar line  highLine  = na\nvar label highLabel = na\n\nif barstate.islast\n    line.delete(highLine)\n    label.delete(highLabel)\n\n    startBar = bar_index - adaptedLen + 1\n\n    highLine := line.new(\n         x1     = startBar,\n         y1     = weekHigh52,\n         x2     = bar_index,\n         y2     = weekHigh52,\n         xloc   = xloc.bar_index,\n         extend = extend.right,\n         color  = lineColorHigh,\n         style  = _lineStyle(lineStyle),\n         width  = lineWidth)\n\n    // ── Chart label (left side of line) ──\n    if showLabel\n        distStr  = showDist ? \" (\" + (distPct >= 0 ? \"+\" : \"\") + str.tostring(distPct, \"#.##\") + \"%)\" : \"\"\n        barsNote = adaptedLen < IDEAL_BARS ? \" [\" + str.tostring(adaptedLen) + \"d]\" : \"\"\n        labelTxt = \"52W High: \" + str.tostring(weekHigh52, format.mintick) + distStr + barsNote\n\n        highLabel := label.new(\n             x         = startBar,\n             y         = weekHigh52,\n             text      = labelTxt,\n             xloc      = xloc.bar_index,\n             yloc      = yloc.price,\n             style     = label.style_label_right,\n             color     = color.new(lineColorHigh, 80),\n             textcolor = lineColorHigh,\n             size      = size.small)\n\n// ─── Data Window only ─────────────────────────────────────────────────────────\nplot(weekHigh52, \"52W High\",            display=display.data_window)\nplot(distPct,    \"Dist% from 52W High\", display=display.data_window)\n\n// ─── Alerts ───────────────────────────────────────────────────────────────────\nalertcondition(isNearHigh,                      \"Near 52W High\",  \"Price is near the 52-Week High!\")\nalertcondition(ta.crossover(close, weekHigh52), \"Broke 52W High\", \"Price broke above the 52-Week High!\")\n",
  "maSpectrum": "//@version=6\nindicator(\"MA Spectrum 7\", overlay=true, timeframe=\"\", timeframe_gaps=true)\n\n// ==================================================\n// MA 20 / 50 / 100 / 200 SETTINGS\n// ==================================================\ngroupFast = \"MA 20 / 50 / 100 / 200\"\n\nshowFastGroup = input.bool(true, \"Show all 20 / 50 / 100 / 200\", group=groupFast)\n\nmaTypeFast = input.string(\n     \"EMA\",\n     title=\"Basis MA Type\",\n     options=[\"SMA\", \"EMA\", \"SMMA (RMA)\", \"WMA\", \"VWMA\"],\n     group=groupFast)\n\nsrc = input.source(close, title=\"Source\", group=groupFast)\n\nshow20 = input.bool(true, \"MA 20\", inline=\"ma20\", group=groupFast)\ncol20  = input.color(color.aqua, \"\", inline=\"ma20\", group=groupFast)\n\nshow50 = input.bool(true, \"MA 50\", inline=\"ma50\", group=groupFast)\ncol50  = input.color(color.yellow, \"\", inline=\"ma50\", group=groupFast)\n\nshow100 = input.bool(true, \"MA 100\", inline=\"ma100\", group=groupFast)\ncol100  = input.color(color.orange, \"\", inline=\"ma100\", group=groupFast)\n\nshow200 = input.bool(true, \"MA 200\", inline=\"ma200\", group=groupFast)\ncol200  = input.color(color.red, \"\", inline=\"ma200\", group=groupFast)\n\n// ==================================================\n// MA 350 / 700 / 1400 SETTINGS\n// ==================================================\ngroupLong = \"MA 350 / 700 / 1400\"\n\nshowLongGroup = input.bool(true, \"Show all 350 / 700 / 1400\", group=groupLong)\n\nmaTypeLong = input.string(\n     \"SMA\",\n     title=\"MA Type\",\n     options=[\"SMA\", \"EMA\"],\n     group=groupLong)\n\nshow350 = input.bool(true, \"MA 350\", inline=\"ma350\", group=groupLong)\ncol350  = input.color(#00875A, \"\", inline=\"ma350\", group=groupLong)\n\nshow700 = input.bool(true, \"MA 700\", inline=\"ma700\", group=groupLong)\ncol700  = input.color(#2962FF, \"\", inline=\"ma700\", group=groupLong)\n\nshow1400 = input.bool(true, \"MA 1400\", inline=\"ma1400\", group=groupLong)\ncol1400  = input.color(#7B1FA2, \"\", inline=\"ma1400\", group=groupLong)\n\n// ==================================================\n// MOVING AVERAGE FUNCTIONS\n// ==================================================\ngetMA(source, length, type) =>\n    switch type\n        \"SMA\"        => ta.sma(source, length)\n        \"EMA\"        => ta.ema(source, length)\n        \"SMMA (RMA)\" => ta.rma(source, length)\n        \"WMA\"        => ta.wma(source, length)\n        \"VWMA\"       => ta.vwma(source, length)\n        => na\n\ngetLongMA(source, length, type) =>\n    type == \"EMA\" ? ta.ema(source, length) : ta.sma(source, length)\n\n// ==================================================\n// CALCULATIONS\n// ==================================================\nma20  = getMA(src, 20, maTypeFast)\nma50  = getMA(src, 50, maTypeFast)\nma100 = getMA(src, 100, maTypeFast)\nma200 = getMA(src, 200, maTypeFast)\n\nma350  = getLongMA(close, 350, maTypeLong)\nma700  = getLongMA(close, 700, maTypeLong)\nma1400 = getLongMA(close, 1400, maTypeLong)\n\n// ==================================================\n// PLOTS\n// ==================================================\nplot(showFastGroup and show20 ? ma20 : na, title=\"MA 20\", color=col20)\nplot(showFastGroup and show50 ? ma50 : na, title=\"MA 50\", color=col50)\nplot(showFastGroup and show100 ? ma100 : na, title=\"MA 100\", color=col100)\nplot(showFastGroup and show200 ? ma200 : na, title=\"MA 200\", color=col200)\n\nplot(showLongGroup and show350 ? ma350 : na, title=\"MA 350\", color=col350, linewidth=2)\nplot(showLongGroup and show700 ? ma700 : na, title=\"MA 700\", color=col700, linewidth=2)\nplot(showLongGroup and show1400 ? ma1400 : na, title=\"MA 1400\", color=col1400, linewidth=2)\n",
  "mcdx": "// This Pine Script® code is subject to the terms of the Mozilla Public License 2.0\n// © MCDX Smart Money Indicator - Pine Script v6 Recreation\n// Based on the open-source MCDX formula (RSI-based momentum classifier)\n// Credits: Original concept by Mango2Juice / kgiap123 on TradingView\n//\n// HOW TO READ:\n//   🔴 RED   = Banker (Smart Money / Institutional) → BULLISH signal\n//   🟡 YELLOW = Hot Money (Short-term / Fast traders) → NEUTRAL / cautious\n//   🟢 GREEN  = Retailer (Retail traders) → BEARISH signal (avoid going long)\n//\n//   ✅ Best to go LONG when: RED bars dominate (>50%) and GREEN is low\n//   ❌ Avoid LONG when: GREEN bars dominate (retailers stuck / trapped)\n\n//@version=6\nindicator(title=\"MCDX Smart Money\", shorttitle=\"MCDX\", overlay=false, max_bars_back=500)\n\n// ─── INPUTS ───────────────────────────────────────────────────────────────────\n\nvar string GRP1 = \"🔴 Banker (Smart Money) Settings\"\nbankerBase    = input.int(50,  \"Banker RSI Base\",    minval=10, maxval=90, group=GRP1)\nbankerPeriod  = input.int(50,  \"Banker RSI Period\",  minval=5,  maxval=200, group=GRP1)\nbankerSens    = input.float(1.5, \"Banker Sensitivity\", minval=0.1, maxval=10.0, step=0.1, group=GRP1)\n\nvar string GRP2 = \"🟡 Hot Money Settings\"\nhotBase       = input.int(30,  \"Hot Money RSI Base\",   minval=10, maxval=90, group=GRP2)\nhotPeriod     = input.int(40,  \"Hot Money RSI Period\",  minval=5,  maxval=200, group=GRP2)\nhotSens       = input.float(0.7, \"Hot Money Sensitivity\", minval=0.1, maxval=10.0, step=0.1, group=GRP2)\n\nvar string GRP3 = \"📊 Display Settings\"\nshowMA        = input.bool(true,  \"Show Moving Averages\", group=GRP3)\nmaPeriod      = input.int(10,  \"MA Period\", minval=2, maxval=50, group=GRP3)\nshowBg        = input.bool(true,  \"Show Background Signal\", group=GRP3)\nshowLabels    = input.bool(true,  \"Show % Labels\", group=GRP3)\n\n// ─── COLORS ──────────────────────────────────────────────────────────────────\n\nCOLOR_BANKER   = color.new(color.red,    0)\nCOLOR_HOT      = color.new(#D4AC0D,      0)   // gold/yellow\nCOLOR_RETAIL   = color.new(color.green,  0)\nCOLOR_BANKER_MA = color.new(#FF6B6B,    20)\nCOLOR_HOT_MA   = color.new(#F7DC6F,     20)\nCOLOR_RETAIL_MA = color.new(#58D68D,    20)\n\n// ─── MCDX CALCULATION ────────────────────────────────────────────────────────\n// Formula: sensitivity * (RSI(period) - base), clamped between 0 and 20\n// The \"Retailer\" chip is the remainder: 20 - max(banker, hotmoney)\n\nmcdx_calc(sens, period, base) =>\n    r = ta.rsi(close, period)\n    raw = sens * (r - base)\n    math.max(0.0, math.min(20.0, raw))\n\nbankerVal  = mcdx_calc(bankerSens, bankerPeriod, bankerBase)\nhotVal     = mcdx_calc(hotSens,    hotPeriod,    hotBase)\n\n// Retailer = remaining space up to 20 (after banker takes priority)\n// Retailer fills from the bottom (0 to 20), Banker overlays on top\nretailVal  = math.max(0.0, 20.0 - math.max(bankerVal, hotVal))\n\n// ─── MOVING AVERAGES ─────────────────────────────────────────────────────────\n\nbankerMA  = ta.sma(bankerVal, maPeriod)\nhotMA     = ta.sma(hotVal,    maPeriod)\nretailMA  = ta.sma(retailVal, maPeriod)\n\n// ─── PERCENTAGE LABELS ───────────────────────────────────────────────────────\n\ntotal = bankerVal + hotVal + retailVal\nbankerPct  = total > 0 ? (bankerVal  / total) * 100 : 0.0\nhotPct     = total > 0 ? (hotVal     / total) * 100 : 0.0\nretailPct  = total > 0 ? (retailVal  / total) * 100 : 0.0\n\n// ─── BACKGROUND SIGNAL ───────────────────────────────────────────────────────\n\n// Green BG = Banker dominant (bullish)\n// Red BG   = Retailer dominant (bearish/avoid)\nbgColor = bankerVal > hotVal and bankerVal > retailVal ? color.new(color.green, 92) :\n          retailVal > bankerVal and retailVal > hotVal  ? color.new(color.red,   92) :\n          color.new(color.yellow, 95)\n\nbgcolor(showBg ? bgColor : na, title=\"Background Signal\")\n\n// ─── PLOTS ───────────────────────────────────────────────────────────────────\n\n// Base line at 20 (max level reference)\nhline(20, \"Max Level\",  color=color.new(color.gray, 70), linestyle=hline.style_dashed)\nhline(10, \"Mid Level\",  color=color.new(color.gray, 80), linestyle=hline.style_dotted)\nhline(0,  \"Zero Level\", color=color.new(color.gray, 60), linestyle=hline.style_solid)\n\n// Stacked bars: Retailer (bottom/base = full 20), then Hot Money, then Banker on top\nplot(20,        title=\"Retailer Base\",  style=plot.style_columns, color=COLOR_RETAIL,  linewidth=1)\nplot(hotVal > 0 or bankerVal > 0 ? math.max(hotVal, bankerVal) : na,\n                title=\"Hot Money\",      style=plot.style_columns, color=COLOR_HOT,      linewidth=1)\nplot(bankerVal > 0 ? bankerVal : na,\n                title=\"Banker\",         style=plot.style_columns, color=COLOR_BANKER,   linewidth=1)\n\n// Moving Average Lines\nplot(showMA ? bankerMA  : na, title=\"Banker MA\",  color=COLOR_BANKER_MA,  linewidth=2)\nplot(showMA ? hotMA     : na, title=\"Hot MA\",     color=COLOR_HOT_MA,     linewidth=2)\nplot(showMA ? retailMA  : na, title=\"Retail MA\",  color=COLOR_RETAIL_MA,  linewidth=2)\n\n// ─── INFO TABLE ───────────────────────────────────────────────────────────────\n\nif showLabels and barstate.islast\n    var table infoTable = table.new(position.top_right, 2, 4,\n         bgcolor=color.new(color.black, 70),\n         border_color=color.new(color.gray, 50),\n         border_width=1, frame_color=color.new(color.gray, 50), frame_width=1)\n\n    table.cell(infoTable, 0, 0, \"MCDX\",        text_color=color.white,  text_size=size.small, bgcolor=color.new(color.navy, 30))\n    table.cell(infoTable, 1, 0, \"Value / %\",   text_color=color.silver, text_size=size.small, bgcolor=color.new(color.navy, 30))\n\n    table.cell(infoTable, 0, 1, \"🔴 Banker\",   text_color=color.red,    text_size=size.small)\n    table.cell(infoTable, 1, 1, str.tostring(bankerVal, \"#.##\") + \"  (\" + str.tostring(bankerPct, \"#.#\") + \"%)\",\n               text_color=color.red, text_size=size.small)\n\n    table.cell(infoTable, 0, 2, \"🟡 Hot Money\", text_color=#D4AC0D,     text_size=size.small)\n    table.cell(infoTable, 1, 2, str.tostring(hotVal, \"#.##\") + \"  (\" + str.tostring(hotPct, \"#.#\") + \"%)\",\n               text_color=#D4AC0D, text_size=size.small)\n\n    table.cell(infoTable, 0, 3, \"🟢 Retailer\",  text_color=color.green,  text_size=size.small)\n    table.cell(infoTable, 1, 3, str.tostring(retailVal, \"#.##\") + \"  (\" + str.tostring(retailPct, \"#.#\") + \"%)\",\n               text_color=color.green, text_size=size.small)\n\n// ─── ALERTS ──────────────────────────────────────────────────────────────────\n\nalertcondition(ta.crossover(bankerVal, hotVal),   title=\"Banker Crossover Hot Money\",   message=\"MCDX: Banker crossed above Hot Money — Bullish signal 🔴\")\nalertcondition(ta.crossover(bankerVal, retailVal), title=\"Banker Crossover Retail\",     message=\"MCDX: Banker crossed above Retailer — Strong Bullish 🔴🔴\")\nalertcondition(ta.crossunder(bankerVal, hotVal),  title=\"Banker Crossunder Hot Money\",  message=\"MCDX: Banker fell below Hot Money — Caution ⚠️\")\nalertcondition(bankerVal >= 15,                   title=\"Strong Banker Zone (>= 15)\",   message=\"MCDX: Banker in Strong Zone (≥15) — Institutional accumulation 🏦\")\nalertcondition(retailVal >= 18,                   title=\"Retailer Dominant (>= 18)\",    message=\"MCDX: Retailer dominant — Avoid long, possible distribution 🟢\")\n",
  "zigzag": "//@version=6\nindicator(\"ZigZag [ZZ]\", shorttitle=\"ZZ\", overlay=true, max_lines_count=500, max_labels_count=500)\n\n// ============================================================================\n// ZigZag [ZZ] — Swing High/Low Wave Indicator\n// Connects confirmed swing highs/lows with trend-colored lines, with optional\n// price/% labels and a live \"developing leg\" preview toward the current bar.\n// ============================================================================\n\n// ── Inputs ──────────────────────────────────────────────────────────────\ndepth      = input.int(10, \"Depth (Pivot Strength)\", minval=1, tooltip=\"Bars required on each side of a bar to confirm it as a swing point. Higher = fewer, larger swings. Lower = more, smaller swings.\", group=\"ZigZag Settings\")\nsrcMode    = input.string(\"High/Low\", \"Pivot Source\", options=[\"High/Low\", \"Close\"], group=\"ZigZag Settings\")\n\nshowLabels = input.bool(true, \"Show Price Labels\", group=\"Labels\")\nshowPct    = input.bool(true, \"Show % Change\", group=\"Labels\")\nlabelSize  = input.string(size.small, \"Label Size\", options=[size.tiny, size.small, size.normal, size.large], group=\"Labels\")\n\nlineWidth  = input.int(2, \"Line Width\", minval=1, maxval=6, group=\"Style\")\nupColor    = input.color(#089981, \"Up Leg Color\", group=\"Style\")\ndnColor    = input.color(#f23645, \"Down Leg Color\", group=\"Style\")\nshowDev    = input.bool(true, \"Show Live Developing Leg\", group=\"Style\")\nbgShade    = input.bool(false, \"Shade Background by Trend\", group=\"Style\")\n\n// ── Pivot detection ─────────────────────────────────────────────────────\nuseClose = srcMode == \"Close\"\nfloat ph = useClose ? ta.pivothigh(close, depth, depth) : ta.pivothigh(high, depth, depth)\nfloat pl = useClose ? ta.pivotlow(close, depth, depth)  : ta.pivotlow(low, depth, depth)\n\npivotBar = bar_index - depth\n\n// ── State (persists across bars) ────────────────────────────────────────\nvar int   p2Dir   = 0     // 0 = no pivot yet, 1 = last point is a HIGH, -1 = last point is a LOW\nvar int   p1Bar   = na\nvar float p1Price = na\nvar int   p2Bar   = na\nvar float p2Price = na\nvar line  zzLine  = na\nvar label zzLabel = na\nvar line  devLine = na\n\nnewHighConfirmed = false\nnewLowConfirmed  = false\n\n// ── Helpers ──────────────────────────────────────────────────────────────\nbuildLabelText(_price, _prevPrice) =>\n    txt = str.tostring(_price, format.mintick)\n    if showPct and not na(_prevPrice) and _prevPrice != 0\n        pct = (_price - _prevPrice) / _prevPrice * 100\n        txt := txt + \"\\n\" + (pct >= 0 ? \"+\" : \"\") + str.tostring(pct, \"#.##\") + \"%\"\n    txt\n\nmakeLabel(_bar, _price, _isHigh, _prevPrice) =>\n    label lbl = na\n    if showLabels\n        lbl := label.new(_bar, _price, buildLabelText(_price, _prevPrice),\n                          style=_isHigh ? label.style_label_down : label.style_label_up,\n                          color=color.new(color.white, 100),\n                          textcolor=_isHigh ? dnColor : upColor,\n                          size=labelSize)\n    lbl\n\n// ── Process a new pivot HIGH ──────────────────────────────────────────────\nif not na(ph)\n    if p2Dir <= 0\n        // Reversal: previous point becomes fixed (p1); this high starts the new point (p2)\n        if not na(p2Bar)\n            p1Bar   := p2Bar\n            p1Price := p2Price\n            zzLine  := line.new(p1Bar, p1Price, pivotBar, ph, color=upColor, width=lineWidth)\n            zzLabel := makeLabel(pivotBar, ph, true, p1Price)\n        p2Bar   := pivotBar\n        p2Price := ph\n        p2Dir   := 1\n        newHighConfirmed := true\n    else if ph > p2Price\n        // Continuation: extend the current up-leg to the new, higher high\n        p2Bar   := pivotBar\n        p2Price := ph\n        if not na(zzLine)\n            line.set_x2(zzLine, p2Bar)\n            line.set_y2(zzLine, p2Price)\n        if not na(zzLabel)\n            label.set_x(zzLabel, p2Bar)\n            label.set_y(zzLabel, p2Price)\n            label.set_text(zzLabel, buildLabelText(p2Price, p1Price))\n\n// ── Process a new pivot LOW ───────────────────────────────────────────────\nif not na(pl)\n    if p2Dir >= 0\n        // Reversal: previous point becomes fixed (p1); this low starts the new point (p2)\n        if not na(p2Bar)\n            p1Bar   := p2Bar\n            p1Price := p2Price\n            zzLine  := line.new(p1Bar, p1Price, pivotBar, pl, color=dnColor, width=lineWidth)\n            zzLabel := makeLabel(pivotBar, pl, false, p1Price)\n        p2Bar   := pivotBar\n        p2Price := pl\n        p2Dir   := -1\n        newLowConfirmed := true\n    else if pl < p2Price\n        // Continuation: extend the current down-leg to the new, lower low\n        p2Bar   := pivotBar\n        p2Price := pl\n        if not na(zzLine)\n            line.set_x2(zzLine, p2Bar)\n            line.set_y2(zzLine, p2Price)\n        if not na(zzLabel)\n            label.set_x(zzLabel, p2Bar)\n            label.set_y(zzLabel, p2Price)\n            label.set_text(zzLabel, buildLabelText(p2Price, p1Price))\n\n// ── Live developing leg (dotted preview from last confirmed point to now) ──\nif showDev and not na(p2Bar)\n    if na(devLine)\n        devLine := line.new(p2Bar, p2Price, bar_index, close, color=color.gray, style=line.style_dotted, width=1)\n    else\n        line.set_x1(devLine, p2Bar)\n        line.set_y1(devLine, p2Price)\n        line.set_x2(devLine, bar_index)\n        line.set_y2(devLine, close)\n\n// ── Optional trend background shading ──────────────────────────────────────\nbgcolor(bgShade ? (p2Dir == 1 ? color.new(upColor, 92) : p2Dir == -1 ? color.new(dnColor, 92) : na) : na)\n\n// ── Alerts ──────────────────────────────────────────────────────────────\nalertcondition(newHighConfirmed, title=\"ZZ New Swing High\", message=\"ZZ: new confirmed swing HIGH\")\nalertcondition(newLowConfirmed,  title=\"ZZ New Swing Low\",  message=\"ZZ: new confirmed swing LOW\")\n"
};
